class FfiConverterTypeMdbxVault: FfiConverter<MdbxVault, ulong> {
    public static FfiConverterTypeMdbxVault INSTANCE = new FfiConverterTypeMdbxVault();


    public override ulong Lower(MdbxVault value) {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override MdbxVault Lift(ulong value) {
        return new MdbxVault(value);
    }

    public override MdbxVault Read(BigEndianStream stream) {
        return Lift(stream.ReadULong());
    }

    public override int AllocationSize(MdbxVault value) {
        return 8;
    }

    public override void Write(MdbxVault value, BigEndianStream stream) {
        stream.WriteULong(Lower(value));
    }
}



public record EntryRecord (
    string EntryId, 
    string ProjectId, 
    string EntryType, 
    string Title, 
    string PayloadJson, 
    bool Deleted
) {
}

class FfiConverterTypeEntryRecord: FfiConverterRustBuffer<EntryRecord> {
    public static FfiConverterTypeEntryRecord INSTANCE = new FfiConverterTypeEntryRecord();

    public override EntryRecord Read(BigEndianStream stream) {
        return new EntryRecord(
            EntryId: FfiConverterString.INSTANCE.Read(stream),
            ProjectId: FfiConverterString.INSTANCE.Read(stream),
            EntryType: FfiConverterString.INSTANCE.Read(stream),
            Title: FfiConverterString.INSTANCE.Read(stream),
            PayloadJson: FfiConverterString.INSTANCE.Read(stream),
            Deleted: FfiConverterBoolean.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(EntryRecord value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.EntryId)
            + FfiConverterString.INSTANCE.AllocationSize(value.ProjectId)
            + FfiConverterString.INSTANCE.AllocationSize(value.EntryType)
            + FfiConverterString.INSTANCE.AllocationSize(value.Title)
            + FfiConverterString.INSTANCE.AllocationSize(value.PayloadJson)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.Deleted);
    }

    public override void Write(EntryRecord value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.EntryId, stream);
            FfiConverterString.INSTANCE.Write(value.ProjectId, stream);
            FfiConverterString.INSTANCE.Write(value.EntryType, stream);
            FfiConverterString.INSTANCE.Write(value.Title, stream);
            FfiConverterString.INSTANCE.Write(value.PayloadJson, stream);
            FfiConverterBoolean.INSTANCE.Write(value.Deleted, stream);
    }
}



